63		idx := slices.IndexFunc(cols, func(c datatable.Column[agentRow]) bool { return c.Title == breakdownTitle })
64		if idx < 0 {
65			t.Fatalf("agentColumns has no %q column", breakdownTitle)
66		}
67		if cols[idx-1].Title != "Model" || cols[idx+1].Title != "In" {
68			t.Errorf("%s sits between %q and %q, want between Model and In", breakdownTitle, cols[idx-1].Title, cols[idx+1].Title)
69		}
70		c := cols[idx]
71		if !c.Optional || c.DropFirst {
72			t.Errorf("Optional=%v DropFirst=%v, want Optional and not DropFirst", c.Optional, c.DropFirst)
73		}
74		if c.Sizing != datatable.SizingFixed || c.MinWidth != 10 || breakdownBarWidth != 10 {
75			t.Errorf("Sizing=%v MinWidth=%d, want SizingFixed and 10", c.Sizing, c.MinWidth)
76		}
77		if c.Less != nil || c.Search != nil {
78			t.Errorf("Less set=%v Search set=%v, want neither", c.Less != nil, c.Search != nil)
79		}
80		if c.Spans == nil || c.Cell == nil || c.Style == nil {
81			t.Errorf("Spans/Cell/Style set = %v/%v/%v, want all", c.Spans != nil, c.Cell != nil, c.Style != nil)
82		}
83		if c.Cut != nil || c.TailStyle != nil {
84			t.Error("Spans takes precedence over Cut/TailStyle; the column must not declare them")
85		}
86	}
