88	func TestBreakdownCellAndSpansForATypicalAgent(t *testing.T) {
89		c := column(t, breakdownTitle)
90		r := rowOf(t, mixAgent())
91		if got, want := c.Cell(r), theme.GaugeFill(10); got != want || strings.Contains(got, "\x1b") || len([]rune(got)) != 10 {
92			t.Errorf("Cell = %q, want ten plain gauge glyphs %q", got, want)
93		}
94		want, ok := segmentCells(r.Tokens)
95		if !ok {
96			t.Fatal("precondition: the fixture agent has tokens")
97		}
98		if want != [segCount]int{1, 3, 1, 5} {
99			t.Fatalf("precondition: segmentCells = %v, want [1 3 1 5]", want)
100		}
101		spans := c.Spans(r)
102		if len(spans) != segCount {
103			t.Fatalf("got %d spans, want %d", len(spans), segCount)
104		}
105		roles := theme.TokenRoles() // Input, Output, Cache write, Cache read
106		if len(roles) != segCount {
107			t.Fatalf("theme has %d token roles, want %d", len(roles), segCount)
108		}
109		total := 0
110		for i, s := range spans {
111			if s.Width != want[i] {
112				t.Errorf("span %d width = %d, want %d", i, s.Width, want[i])
113			}
114			if got, wantFg := s.Style.GetForeground(), theme.TokenStyle(roles[i]).GetForeground(); got != wantFg {
115				t.Errorf("span %d foreground = %v, want %v (%s)", i, got, wantFg, roles[i])
116			}
117			total += s.Width
118		}
119		if total != 10 {
120			t.Errorf("spans add up to %d cells, want 10", total)
121		}
122	}
