194				sum.Output += b.Tokens.Output
195				sum.CacheRead += b.Tokens.CacheRead
196				sum.CacheWrite += b.Tokens.CacheWrite
197			}
198			if sum != a.Tokens {
199				t.Errorf("agent %q: ByModel sums to %+v, Tokens is %+v", a.ID, sum, a.Tokens)
