247	// Rule 116 at every width from 50 to 230, the bar column coming and going, and
248	// the order in which optional columns give way holds at each of them.
249	func TestBreakdownRule116AndDropOrderAtEveryWidth(t *testing.T) {
250		// Optional columns in the order they disappear: Cache write, Est. cost, Cache read, In, Breakdown, Model, Duration, Tools, State.
251		vanish := []string{"Cache write", "Est. cost", "Cache read", "In", breakdownTitle, "Model", "Duration", "Tools", "State"}
252		shown, widths := 0, 0
253		for w := 50; w <= 230; w++ {
254			m := atPricedAgents(t, nil, w, costUsage())
255			widths++
256			if got := m.agentTable.RenderedWidth(); got != w-2 {
257				t.Fatalf("width %d: rendered width = %d, want %d (Rule 116)", w, got, w-2)
258			}
259			cols := shownTitles(t, m.View())
260			if i := slices.Index(cols, breakdownTitle); i >= 0 {
261				shown++
262				if cols[i-1] != "Model" || cols[i+1] != "In" && cols[i+1] != "Out" {
263					t.Fatalf("width %d: %s sits between %q and %q: %v", w, breakdownTitle, cols[i-1], cols[i+1], cols)
264				}
265			}
266			// A column that is gone means every column that goes before it is gone.
267			for i, gone := range vanish {
268				if slices.Contains(cols, gone) {
269					continue
270				}
271				for _, kept := range vanish[:i] {
272					if slices.Contains(cols, kept) {
