274					}
275				}
276			}
277		}
278		if widths != 181 {
279			t.Fatalf("checked %d widths, want 181 (50..230)", widths)
280		}
281		if shown == 0 {
282			t.Fatal("Breakdown never appears between 50 and 230 columns")
283		}
