336	// changes its spans and only its spans.
337	func TestBreakdownFollowsALiveUpdate(t *testing.T) {
338		before := agentusage.Usage{Agents: []agentusage.Agent{
339			{Main: true, Tokens: agentusage.Tokens{Input: 500, Output: 500}},
340			{ID: "a01", Type: "coder", Tokens: agentusage.Tokens{Input: 500, Output: 500}},
